package org.eclipse.rdf4j.sail.lmdb.benchmark;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.benchmark.common.ThemeQueryCatalog;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.repository.util.RDFInserter;
import org.eclipse.rdf4j.sail.lmdb.LmdbBenchmarkQueryPlan;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

class LmdbPharmaQ2BoundJoinProductEstimateIT {

	private static final ValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();
	private static final Theme THEME = Theme.PHARMA;
	private static final IRI PHARMA_ARM_DRUG = VALUE_FACTORY.createIRI("http://example.com/theme/pharma/armDrug");
	private static final IRI PHARMA_HAS_ARM = VALUE_FACTORY.createIRI("http://example.com/theme/pharma/hasArm");
	private static final IRI PHARMA_TARGETS = VALUE_FACTORY.createIRI("http://example.com/theme/pharma/targets");

	@Test
	@Timeout(300)
	void pharmaQ2DoesNotStartFromBroadTargetsScan(@TempDir Path dataDir) throws Exception {
		Path themeDir = prepareThemeStore(dataDir);
		try {
			LmdbStore store = new LmdbStore(themeDir.toFile(), ConfigUtil.createConfig());
			SailRepository repository = new SailRepository(store);
			try {
				repository.init();
				BenchmarkJoinEstimatorSupport.awaitEstimatorReady(store, "pharma-q2 bound product", 60,
						TimeUnit.SECONDS);
				OptimizerSnapshot snapshot = explainOptimized(store, repository);

				String diagnostics = "PHARMA q2 should cost the object-bound pharma:targets lookup below "
						+ "the broad predicate scan once target type and pathway have prepared the target domain."
						+ "\nquery:\n" + snapshot.renderedQuery()
						+ "\noptimized plan:\n" + snapshot.plan();
				assertConnectedPlanDoesNotStartFromTargetsScan(snapshot.plan(), diagnostics);
				assertExistsStartsFromBoundArmDrugLookup(snapshot.plan(), diagnostics);
			} finally {
				shutdownAndRelease(repository, store);
			}
		} finally {
			BenchmarkJoinEstimatorSupport.deleteStoreDirectory(themeDir);
		}
	}

	private static void assertConnectedPlanDoesNotStartFromTargetsScan(String plan, String diagnostics) {
		String targetsAccess = firstStatementPattern(plan, PHARMA_TARGETS.stringValue());
		assertTrue(targetsAccess != null,
				"PHARMA q2 physical plan should expose the pharma:targets access path.\n" + diagnostics);
		assertTrue(targetsAccess.contains("plannedLookupComponents=[S, P]")
				|| targetsAccess.contains("plannedLookupComponents=[P, O]"),
				"PHARMA q2 must use a bound pharma:targets prefix lookup rather than a predicate-only scan.\n"
						+ "targets access:\n" + targetsAccess + "\n" + diagnostics);
	}

	private static void assertExistsStartsFromBoundArmDrugLookup(String plan, String diagnostics) {
		int armDrugLine = firstStatementPatternLine(plan, PHARMA_ARM_DRUG.stringValue());
		int hasArmLine = firstStatementPatternLine(plan, PHARMA_HAS_ARM.stringValue());
		assertTrue(armDrugLine >= 0,
				"PHARMA q2 EXISTS plan should expose the bound armDrug lookup.\n" + diagnostics);
		assertTrue(hasArmLine >= 0,
				"PHARMA q2 EXISTS plan should expose the hasArm lookup.\n" + diagnostics);
		assertTrue(armDrugLine < hasArmLine,
				"PHARMA q2 correlated EXISTS should use the outer-bound ?drug armDrug lookup before broad hasArm.\n"
						+ "armDrug line=" + armDrugLine + ", hasArm line=" + hasArmLine + "\n"
						+ diagnostics);
	}

	private static String firstStatementPattern(String plan, String predicate) {
		return plan.lines()
				.filter(line -> line.contains("StatementPattern") && line.contains(predicate))
				.findFirst()
				.orElse(null);
	}

	private static int firstStatementPatternLine(String plan, String predicate) {
		String[] lines = plan.split("\\R");
		for (int i = 0; i < lines.length; i++) {
			if (lines[i].contains("StatementPattern") && lines[i].contains(predicate)) {
				return i;
			}
		}
		return -1;
	}

	private static Path prepareThemeStore(Path dataDir) throws Exception {
		BenchmarkJoinEstimatorSupport.ThemeRegressionStore preparedStore = BenchmarkJoinEstimatorSupport
				.prepareThemeRegressionStore(
						dataDir.resolve(THEME.name()),
						"pharma-q2-bound-product-estimate",
						storeDirectory -> {
							LmdbStore store = new LmdbStore(storeDirectory.toFile(), ConfigUtil.createConfig());
							SailRepository repository = new SailRepository(store);
							try {
								loadData(repository);
							} finally {
								repository.shutDown();
							}
						});
		return preparedStore.storeDirectory();
	}

	private static void loadData(SailRepository repository) throws IOException {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			RDFInserter inserter = new RDFInserter(connection);
			connection.begin(IsolationLevels.NONE);
			ThemeDataSetGenerator.generate(THEME, inserter);
			connection.commit();
		}
	}

	private static OptimizerSnapshot explainOptimized(LmdbStore store, SailRepository repository) {
		String traceProperty = "rdf4j.optimizer.lmdb.cascades.connectedJoin.trace";
		String traceLimitProperty = "rdf4j.optimizer.lmdb.cascades.connectedJoin.traceLimit";
		String previousTrace = System.getProperty(traceProperty);
		String previousTraceLimit = System.getProperty(traceLimitProperty);
		System.setProperty(traceProperty, "true");
		System.setProperty(traceLimitProperty, "120000");
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				String query = ThemeQueryCatalog.queryFor(THEME, 2);
				try (LmdbBenchmarkQueryPlan plan = LmdbBenchmarkQueryPlan.prepare(store, connection,
						query, 60)) {
					return new OptimizerSnapshot(plan.optimizedPlan(), query);
				}
			}
		} finally {
			restoreProperty(traceProperty, previousTrace);
			restoreProperty(traceLimitProperty, previousTraceLimit);
		}
	}

	private static void restoreProperty(String name, String value) {
		if (value == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, value);
		}
	}

	private static void shutdownAndRelease(SailRepository repository, LmdbStore store) throws IOException {
		try {
			BenchmarkJoinEstimatorSupport.releaseEstimatorMemory(store);
		} finally {
			repository.shutDown();
		}
	}

	private record OptimizerSnapshot(String plan, String renderedQuery) {
	}
}
